if (!root->isLeaf) {
    const std::vector<Node*>& children = root->ptr2TreeOrData.ptr2Tree;
    for (Node* childNode : children) {
        if (childNode == child) {
            return root;
        }
    }
    // Recursively search in children
    for (Node* childNode : children) {
        Node* parent = find_parent(childNode, child);
        if (parent) {
            return parent;
        }
    }
}

// Leaf nodes cannot have children, so no parent to be found here
return nullptr;

